const NOTICIAS = [{"id": "2026-10-17-codalario-genero-infimo", "fecha": "2026-10-17", "medio": "Codalario", "url": "https://www.codalario.com/nuria-blanco-alvarez/portada/articulo-que-es-el-genero-infimo.-por-nuria-blanco-alvarez_14993_2_49966_0_1_in.html", "titulo": "La serie de Codalario sobre la zarzuela dedica su nueva entrega al género ínfimo", "texto": "La nueva entrega de la serie de Codalario firmada por la musicóloga Nuria Blanco Álvarez sitúa el nacimiento del género ínfimo en los primeros años del siglo XX, como derivación de la revista sicalíptica, con antecedentes en el género bufo y en la tonadilla escénica. La autora explica que el nombre procede de «El género ínfimo», obra de Tomás Barrera y Joaquín Valverde Sanjuán estrenada en el Teatro Apolo en 1901, y señala «La corte de Faraón», de Vicente Lleó, como pieza paradigmática del género. Según Codalario, 17 de octubre.", "etiquetas": ["genero-infimo", "musicologia", "publicaciones", "siglo-xx"], "pais": "ES", "anio": "2026", "obras": [{"id": "la-corte-de-faraon", "t": "La corte de Faraón"}], "personas": [{"id": "tomas-barrera-saavedra", "n": "Tomás Barrera Saavedra"}, {"id": "joaquin-valverde-sanjuan", "n": "Joaquín Valverde Sanjuán"}, {"id": "vicente-lleo", "n": "Vicente Lleó"}], "comp": [{"t": "consta", "txt": "La corte de Faraón, de Vicente Lleó, consta en nuestras fuentes estrenada en el Teatro Eslava de Madrid en 1910.", "ficha": {"tipo": "obra", "id": "la-corte-de-faraon", "n": "La corte de Faraón"}}, {"t": "aporta", "txt": "Nuestras fuentes precisan la fecha del estreno de La corte de Faraón, el 21 de enero de 1910, y sus libretistas, Guillermo Perrín y Miguel de Palacios.", "ficha": {"tipo": "obra", "id": "la-corte-de-faraon", "n": "La corte de Faraón"}}, {"t": "consta", "txt": "Tomás Barrera y Joaquín Valverde Sanjuán constan como compositores en nuestras fuentes.", "ficha": {"tipo": "persona", "id": "joaquin-valverde-sanjuan", "n": "Joaquín Valverde Sanjuán"}}, {"t": "nocons", "txt": "La obra «El género ínfimo» (1901) no tiene todavía ficha en la Zarzuteca, y la fecha exacta de su estreno no consta en nuestras fuentes.", "ficha": null}]}, {"id": "2026-10-15-anuario-sgae-2026-genero-lirico", "fecha": "2026-10-15", "medio": "Scherzo", "url": "https://scherzo.es/la-musica-en-vivo-se-consolida-mientras-el-cine-pierde-espectadores-segun-el-anuario-sgae-2026/", "titulo": "El Anuario SGAE cifra en 1.360 las funciones de ópera y zarzuela de 2025, un 15 % más que el año anterior", "texto": "La Fundación SGAE presentó el 15 de octubre la vigesimosexta edición del Anuario SGAE de las artes escénicas, musicales y audiovisuales, con los datos de 2025. El género lírico sumó 1.360 funciones de ópera y zarzuela, un 15 % más que en 2024, con más de 560.000 espectadores y 19,19 millones de euros de recaudación, aunque la asistencia sigue un 27,2 % por debajo de la de 2019. Cataluña fue la comunidad con más espectadores, 158.000, por delante de Madrid. Según Scherzo, 15 de octubre.", "etiquetas": ["instituciones", "sgae", "publicaciones", "estadistica"], "pais": "ES", "anio": "2026", "obras": [], "personas": [], "comp": [{"t": "consta", "txt": "La nota de prensa de la SGAE confirma la vigesimosexta edición del Anuario y su presentación el 15 de octubre de 2026 en la sede de la SGAE en Madrid.", "ficha": null}, {"t": "nocons", "txt": "El desglose de las cifras del género lírico no consta en la nota oficial de la SGAE; procede del artículo de Scherzo.", "ficha": null}, {"t": "nocons", "txt": "Cuántas de las 1.360 funciones son de zarzuela y cuántas de ópera no consta en nuestras fuentes.", "ficha": null}]}, {"id": "2026-10-11-concurso-logrono-premios-zarzuela", "fecha": "2026-10-11", "medio": "Ópera Actual", "url": "https://www.operaactual.com/noticia/iria-goti-y-milan-perisic-ganan-el-43o-concurso-de-logrono/", "titulo": "El Concurso de Canto Ciudad de Logroño falla sus premios y entrega un trofeo al mejor intérprete de zarzuela", "texto": "El 43º Concurso Internacional de Canto Ciudad de Logroño falló sus premios el 10 de octubre en el Auditorio del Ayuntamiento. Los primeros premios, de 5.000 euros, fueron para la soprano Iria Goti y el barítono Milan Perisic. El Trofeo C.L.A. Pepe Eizaga, en memoria de Manuel Ausensi, al mejor intérprete de zarzuela, recayó en el barítono Javier Povedano; el Trofeo Antón García Abril al mejor intérprete de canción española, en el contratenor Álvaro Basco. El jurado lo presidió José Antonio Toyas. Según Ópera Actual, 11 de octubre.", "etiquetas": ["concursos", "interpretes", "zarzuela", "premios"], "pais": "ES", "anio": "2026", "obras": [], "personas": [], "comp": [{"t": "nocons", "txt": "Ninguno de los premiados ni de los nombres que dan título a los trofeos consta en la Zarzuteca, que recoge autores históricos y no intérpretes en activo. En particular, el barítono Manuel Ausensi y el compositor Antón García Abril no tienen ficha.", "ficha": null}, {"t": "nocons", "txt": "No consta en nuestras fuentes qué obras cantaron los premiados ni en qué consiste la prueba de zarzuela del certamen.", "ficha": null}]}, {"id": "2026-10-10-teatro-zarzuela-170-anios-dia-mundial", "fecha": "2026-10-10", "medio": "Scherzo", "url": "https://scherzo.es/el-teatro-de-la-zarzuela-celebra-su-170o-aniversario/", "titulo": "El Teatro de la Zarzuela cumple 170 años y propone el 10 de octubre como Día Mundial de la Zarzuela", "texto": "El Teatro de la Zarzuela cumplió 170 años el 10 de octubre. Abrió en 1856 por iniciativa de los compositores Francisco Asenjo Barbieri y Joaquín Gaztambide, el libretista Luis Olona y el cantante Francisco Salas. La jornada incluyó la emisión en directo de «No es un día cualquiera», de RNE, una nueva edición de «Mujeres de Zarzuela», con Wikiesfera, para dar entrada en Wikipedia a cerca de treinta profesionales del género, y la ampliación a ocho lenguas del juego «¡Qué comience la función!». El teatro propone el 10 de octubre como Día Mundial de la Zarzuela. Según Scherzo, 10 de octubre.", "etiquetas": ["instituciones", "teatro-de-la-zarzuela", "aniversario", "patrimonio"], "pais": "ES", "anio": "2026", "obras": [], "personas": [{"id": "francisco-asenjo-barbieri", "n": "Francisco Asenjo Barbieri"}, {"id": "joaquin-gaztambide", "n": "Joaquín Gaztambide"}, {"id": "luis-olona", "n": "Luis Olona"}], "comp": [{"t": "consta", "txt": "Tres de los cuatro fundadores que cita la fuente tienen ficha en la Zarzuteca: los compositores Francisco Asenjo Barbieri y Joaquín Gaztambide y el libretista Luis Olona.", "ficha": null}, {"t": "aporta", "txt": "Luis de Olona y Gaeta (Málaga, 1823 – Sarrià, Barcelona, 13 de junio de 1863) estrenó en 1849 «El duende», con música de Rafael Hernando, obra con la que quedó inaugurada la zarzuela restaurada.", "ficha": {"tipo": "persona", "id": "luis-olona", "n": "Luis Olona"}}, {"t": "aporta", "txt": "Francisco Asenjo Barbieri (Madrid, 3 de agosto de 1823 – Madrid, 19 de febrero de 1894) fue compositor, director de orquesta y musicólogo, y aportó ideas sobre la arquitectura y la acústica de la sala.", "ficha": {"tipo": "persona", "id": "francisco-asenjo-barbieri", "n": "Francisco Asenjo Barbieri"}}, {"t": "nocons", "txt": "El cantante Francisco Salas, cuarto impulsor del proyecto, no consta todavía en este archivo. Tampoco «El sonámbulo», la cantata y zarzuela de Emilio Arrieta que figuró en el programa inaugural de 1856.", "ficha": null}, {"t": "nocons", "txt": "No consta en nuestras fuentes si la declaración del 10 de octubre como Día Mundial de la Zarzuela se ha solicitado formalmente ante algún organismo.", "ficha": null}]}, {"id": "2026-10-10-codalario-genero-bufo-nuria-blanco", "fecha": "2026-10-10", "medio": "Codalario", "url": "https://www.codalario.com/genero-bufo/portada/articulo-origen-del-genero-bufo.-por-nuria-blanco-alvarez_14981_2_49923_0_1_in.html", "titulo": "La serie de Codalario sobre la zarzuela dedica su nueva entrega al origen del género bufo", "texto": "La nueva entrega de la serie de Codalario firmada por la musicóloga Nuria Blanco Álvarez sitúa el origen del género bufo español en el modelo de los Bouffes Parisiens de Jacques Offenbach, cuyo «Orphée aux enfers» llegó al Teatro de la Zarzuela en 1864 como «Los dioses del Olimpo», en arreglo de Mariano Pina Bohigas. La autora atribuye a Francisco Arderíus la creación de los Bufos Madrileños, instalados en el Teatro de Variedades en 1866, y señala «El joven Telémaco», de José Rogel y Eusebio Blasco, como la obra que fijó el modelo. Según Codalario, 10 de octubre.", "etiquetas": ["genero-bufo", "divulgacion", "publicaciones", "siglo-xix"], "pais": "ES", "anio": "2026", "obras": [{"id": "los-dos-ciegos", "t": "Los dos ciegos"}, {"id": "el-duende", "t": "El duende"}], "personas": [{"id": "jacques-offenbach", "n": "Jacques Offenbach"}, {"id": "jose-rogel", "n": "José Rogel"}, {"id": "mariano-pina-bohigas", "n": "Mariano Pina Bohigas"}, {"id": "rafael-hernando", "n": "Rafael Hernando"}, {"id": "cristobal-oudrid", "n": "Cristóbal Oudrid"}, {"id": "manuel-fernandez-caballero", "n": "Manuel Fernández Caballero"}, {"id": "emilio-arrieta", "n": "Emilio Arrieta"}, {"id": "francisco-asenjo-barbieri", "n": "Francisco Asenjo Barbieri"}, {"id": "joaquin-gaztambide", "n": "Joaquín Gaztambide"}], "comp": [{"t": "consta", "txt": "La ficha de Jacques Offenbach refrenda, por su cuenta, lo que sostiene el artículo: su música sonó en castellano por primera vez en 1864 con «Los dioses del Olimpo», estrenada en el Teatro de la Zarzuela en la versión que Mariano Pina Bohigas hizo de «Orphée aux Enfers». Sin discrepancia con la fuente.", "ficha": {"tipo": "persona", "id": "jacques-offenbach", "n": "Jacques Offenbach"}}, {"t": "aporta", "txt": "«Los dos ciegos», la primera aproximación española a Offenbach que cita el artículo, se estrenó el 25 de noviembre de 1855 en el Teatro del Circo de Madrid, con música de Francisco Asenjo Barbieri y libreto de Luis Olona. La fuente da el año, pero no la fecha ni el teatro.", "ficha": {"tipo": "obra", "id": "los-dos-ciegos", "n": "Los dos ciegos"}}, {"t": "aporta", "txt": "«El duende», con la que el artículo sitúa el nacimiento de la zarzuela restaurada en el Teatro de Variedades, se estrenó allí el 6 de junio de 1849, con música de Rafael Hernando y libreto de Luis Olona.", "ficha": {"tipo": "obra", "id": "el-duende", "n": "El duende"}}, {"t": "consta", "txt": "Tienen ficha propia los compositores que el artículo cita como primeros autores del género bufo o de su entorno: José Rogel, Emilio Arrieta, Francisco Asenjo Barbieri, Joaquín Gaztambide, Cristóbal Oudrid, Manuel Fernández Caballero y Rafael Hernando.", "ficha": null}, {"t": "nocons", "txt": "«El joven Telémaco», la obra que según el artículo fijó el modelo del género, no consta todavía en este archivo, aunque sí su compositor, José Rogel. Tampoco constan «Los dioses del Olimpo» como obra propia, el libretista Eusebio Blasco, el empresario Francisco Arderíus ni la cantante María Bardán.", "ficha": null}]}, {"id": "2026-10-09-legado-higueras-palatin-victor-espinos", "fecha": "2026-10-09", "medio": "Melómano", "url": "https://www.melomanodigital.com/presentacion-en-madrid-del-legado-higueras-palatin/", "titulo": "La Biblioteca Musical Víctor Espinós recibe el archivo de Mari Lola Higueras y Lola Palatín", "texto": "La Biblioteca Musical Víctor Espinós de Madrid presenta el 22 de octubre el legado Higueras-Palatín, archivo donado por la familia de la arpista Mari Lola Higueras y de su madre, la violinista Lola Palatín. Son catorce archivadores con miles de piezas —críticas, programas, fotografías y manuscritos de obras inéditas y dedicadas— que cubren unos sesenta años de vida musical. La exposición de la Universidad Complutense sobre ambas intérpretes permanece en la biblioteca hasta el 8 de diciembre. Según Melómano, 9 de octubre.", "etiquetas": ["archivos", "patrimonio", "partituras", "exposiciones"], "pais": "ES", "anio": "2026", "obras": [], "personas": [], "comp": [{"t": "nocons", "txt": "La fuente no cita ningún compositor ni ningún título del legado, de modo que no consta en nuestras fuentes si contiene material de zarzuela o de teatro lírico español.", "ficha": null}]}, {"id": "2026-10-08-bohemios-proyecto-zarza-yamawards", "fecha": "2026-10-08", "medio": "Ópera Latinoamérica", "url": "https://www.operala.org/bohemios-teatro-de-la-zarzuela-mejor-opera-yamawards-2026/", "titulo": "«Bohemios» del Proyecto Zarza gana el premio a la mejor ópera en los YAMawards 2026", "texto": "La producción de «Bohemios» del Proyecto Zarza, del Teatro de la Zarzuela, ha ganado el premio a la mejor ópera en los YAMawards 2026, que distinguen espectáculos musicales dirigidos a público infantil y juvenil. El fallo se dio a conocer el 29 de septiembre en Helsingør (Dinamarca), dentro de la YAMsession, entre más de setenta propuestas de diecisiete países. La zarzuela de Amadeo Vives se presentó con dirección escénica de Nicola Beller Carbone, dirección musical de Julio César Picos y músicos de la JONDE. Según Ópera Latinoamérica, 8 de octubre.", "etiquetas": ["zarzuela", "premios", "teatro-de-la-zarzuela", "jovenes"], "pais": "ES", "anio": "2026", "obras": [{"id": "bohemios", "t": "Bohemios"}], "personas": [{"id": "amadeo-vives", "n": "Amadeo Vives"}, {"id": "guillermo-perrin", "n": "Guillermo Perrín"}, {"id": "miguel-de-palacios", "n": "Miguel de Palacios"}], "comp": [{"t": "consta", "txt": "«Bohemios» y su compositor, Amadeo Vives, tienen ficha en la Zarzuteca.", "ficha": null}, {"t": "aporta", "txt": "«Bohemios» se estrenó el 24 de marzo de 1904 en el Teatro de la Zarzuela de Madrid, con libreto de Guillermo Perrín y Miguel de Palacios. La fuente no da ni la fecha, ni el teatro, ni los libretistas.", "ficha": {"tipo": "obra", "id": "bohemios", "n": "Bohemios"}}, {"t": "consta", "txt": "Cinco de los títulos históricos que la fuente atribuye al Proyecto Zarza tienen ficha propia: «La revoltosa», «El dúo de La africana», «La verbena de la Paloma», «Agua, azucarillos y aguardiente» y «El año pasado por agua».", "ficha": null}, {"t": "nocons", "txt": "«El sobre verde» no consta todavía en este archivo. Tampoco constan «Amores en Zarza», «Yo te querré» ni «La Gran A», montajes propios del proyecto que no pertenecen al repertorio histórico.", "ficha": null}]}, {"id": "2026-10-06-tristana-vigo-huertas-camacho", "fecha": "2026-10-06", "medio": "Ópera Actual", "url": "https://www.operaactual.com/noticia/vigo-recupera-tristana-de-miguel-huertas-camacho/", "titulo": "Amigos de la Ópera de Vigo estrena en Galicia «Tristana», ópera de Miguel Huertas-Camacho sobre Galdós", "texto": "Amigos de la Ópera de Vigo ofreció el 11 de octubre en el Teatro Afundación, dentro de su Otoño Lírico, el estreno en Galicia de «Tristana», ópera de cámara con música de Miguel Huertas-Camacho y libreto de Jorge Volpi sobre la novela de Benito Pérez Galdós y el guion de Luis Buñuel y Julio Alejandro. Cantaron Julia Heras, Pablo Rossi Rodino y César Arrieta, con la actriz Luisa Torregrosa, dirección musical de Bauti Carmena y escena de Ricardo Campelo. La obra se estrenó en 2025 en El Escorial. Según Ópera Actual, 6 de octubre.", "etiquetas": ["opera-espanola", "estreno", "galicia"], "pais": "ES", "anio": "2026", "obras": [], "personas": [], "comp": [{"t": "nocons", "txt": "Ni la obra ni Miguel Huertas-Camacho ni Jorge Volpi constan en la Zarzuteca, que no recoge creadores vivos. Tampoco consta todavía Benito Pérez Galdós, autor de la novela de partida.", "ficha": null}, {"t": "nocons", "txt": "No consta en nuestras fuentes el reparto completo: la fuente menciona a Gabriel Alonso en su entradilla y atribuye el papel de Lope a Pablo Rossi Rodino en el reparto.", "ficha": null}]}, {"id": "2026-10-03-codalario-revista-musical-nuria-blanco", "fecha": "2026-10-03", "medio": "Codalario", "url": "https://www.codalario.com/revista-musical/apartado-para-rotacion-de-informaciones-en-la-cabecera/articulo-que-es-la-revista-musical.-por-nuria-blanco-alvarez_14972_34_49878_0_1_in.html", "titulo": "La serie de Codalario sobre el género chico dedica su sexta entrega a la revista musical", "texto": "La sexta entrega de la serie de Codalario sobre el género chico, firmada por la musicóloga Nuria Blanco Álvarez, define la revista musical como zarzuela breve de escenas yuxtapuestas sin enlace argumental, hiladas por un par de personajes y poblada de figuras alegóricas. El artículo distingue la revista del año, la de temporada, la de actualidades, la política y la sicalíptica, y cita «La Gran Vía», «El año pasado por agua» y «¡A ti suspiramos!» entre sus ejemplos. Según Codalario, 3 de octubre.", "etiquetas": ["genero-chico", "divulgacion", "publicaciones"], "pais": "ES", "anio": "2026", "obras": [{"id": "la-gran-via", "t": "La Gran Vía"}, {"id": "el-ano-pasado-por-agua", "t": "El año pasado por agua"}, {"id": "a-ti-suspiramos", "t": "¡A ti suspiramos!"}], "personas": [{"id": "federico-chueca", "n": "Federico Chueca"}, {"id": "joaquin-valverde-duran", "n": "Joaquín Valverde Durán"}, {"id": "manuel-fernandez-caballero", "n": "Manuel Fernández Caballero"}, {"id": "eduardo-navarro-gonzalvo", "n": "Eduardo Navarro Gonzalvo"}, {"id": "rafael-maria-liern-cerach-amalfi", "n": "Rafael María Liern Cerach \"Amalfi\""}, {"id": "salvador-maria-granes", "n": "Salvador María Granés"}, {"id": "emilio-arrieta", "n": "Emilio Arrieta"}, {"id": "manuel-nieto", "n": "Manuel Nieto"}], "comp": [{"t": "consta", "txt": "Tres de las obras que cita el artículo y ocho de los autores que menciona tienen ficha en la Zarzuteca.", "ficha": null}, {"t": "aporta", "txt": "El libreto de «¡A ti suspiramos!» es de Rafael María Liern Cerach «Amalfi» y Salvador María Granés, como recoge su ficha y sin discrepancia con la fuente. La obra se estrenó el 10 de junio de 1889 en el Teatro Maravillas de Madrid.", "ficha": {"tipo": "obra", "id": "a-ti-suspiramos", "n": "¡A ti suspiramos!"}}, {"t": "aporta", "txt": "«La Gran Vía», de Federico Chueca y Joaquín Valverde Durán, se estrenó el 2 de julio de 1886 en el Teatro Felipe de Madrid, con libreto de Felipe Pérez y González.", "ficha": {"tipo": "obra", "id": "la-gran-via", "n": "La Gran Vía"}}, {"t": "nocons", "txt": "Cinco títulos que cita el artículo no constan todavía en este archivo: «El año del diablo», «Los bandos de Villafrita», «Lista de compañía», «Septiembre, Eslava y Compañía» y «1864-65». Tampoco tienen ficha los musicólogos citados, porque la Zarzuteca recoge autores históricos.", "ficha": null}]}, {"id": "2026-10-02-poeta-en-nueva-york-teatro-de-la-zarzuela", "fecha": "2026-10-02", "medio": "Ópera Actual", "url": "https://www.operaactual.com/noticia/con-garcia-lorca-en-la-memoria/", "titulo": "El Teatro de la Zarzuela acoge la ópera de cámara «Poeta en Nueva York», de Alberto Carretero", "texto": "El Teatro de la Zarzuela ofrece el 8 de octubre, en función única, «Poeta en Nueva York», ópera de cámara en un acto con música y libreto de Alberto Carretero sobre textos de Federico García Lorca. Intervienen el cantaor Sergio Gómez «El Colorao», el barítono Javier Povedano y Laura García-Lorca como narradora, con dirección escénica de Rita Cosentino. Es coproducción del Teatro de la Zarzuela y el Espacio Turina de Sevilla, dentro de la temporada dedicada a la Generación del 27. Según Ópera Actual, 2 de octubre.", "etiquetas": ["opera-espanola", "estreno", "instituciones"], "pais": "ES", "anio": "2026", "obras": [], "personas": [], "comp": [{"t": "nocons", "txt": "Ni la obra ni Alberto Carretero ni Federico García Lorca tienen ficha en la Zarzuteca, que recoge autores históricos del teatro lírico español.", "ficha": null}, {"t": "nocons", "txt": "No consta en nuestras fuentes si se trata de un estreno absoluto o de una producción ya vista en el Espacio Turina de Sevilla, ni en qué sala del teatro se representa.", "ficha": null}]}, {"id": "2026-10-01-marina-arrieta-gran-teatro-cordoba", "fecha": "2026-10-01", "medio": "Ópera Actual", "url": "https://www.operaactual.com/entrevista/alejandro-munoz-dirige-marina-en-cordoba-tenemos-un-patrimonio-enorme-que-merece-seguir-presente-en-los-escenarios/", "titulo": "«Marina», de Arrieta, vuelve al Gran Teatro de Córdoba en una nueva producción con el coro de la ciudad", "texto": "El Gran Teatro de Córdoba programa los días 9 y 11 de octubre una nueva producción de «Marina», de Emilio Arrieta, con dirección musical de Alejandro Muñoz y dirección escénica de Juan Carlos Villanueva. Cantan Alba Chantar, Santiago Vidal, Alonso Cano y Julio Nomdedeu, con la Orquesta de Córdoba y el Coro de Ópera de Córdoba, que celebra su 40º aniversario. Muñoz, titular del coro desde 2022, se despide de la formación al acabar la temporada. Según Ópera Actual, 1 de octubre.", "etiquetas": ["zarzuela", "temporada", "interpretes"], "pais": "ES", "anio": "2026", "obras": [{"id": "marina", "t": "Marina"}], "personas": [{"id": "emilio-arrieta", "n": "Emilio Arrieta"}], "comp": [{"t": "consta", "txt": "La obra y su autor tienen ficha en la Zarzuteca.", "ficha": null}, {"t": "aporta", "txt": "«Marina» se estrenó el 21 de septiembre de 1855 en el Teatro del Circo de Madrid, con libreto de Francisco Camprodón, como recoge su ficha. La fuente no da ni la fecha ni el teatro del estreno.", "ficha": {"tipo": "obra", "id": "marina", "n": "Marina"}}, {"t": "nocons", "txt": "No consta en nuestras fuentes si la producción cordobesa sigue la versión de zarzuela de 1855 o la versión de ópera posterior: la fuente no lo precisa. Tampoco consta el reparto de papeles entre los cuatro solistas ni si hay más funciones.", "ficha": null}]}, {"id": "2026-10-01-joan-cervero-director-cndm", "fecha": "2026-10-01", "medio": "Ritmo", "url": "https://www.ritmo.es/actualidad/joan-cervero-se-incorpora-como-nuevo-director-del-centro-nacional-de-difusion-musical", "titulo": "Joan Cerveró se incorpora a la dirección del Centro Nacional de Difusión Musical", "texto": "Joan Cerveró (Manises, Valencia, 1961) se ha incorporado como director del Centro Nacional de Difusión Musical, unidad del INAEM, tras un proceso al que concurrieron 33 candidaturas y que el Consejo Artístico de la Música respaldó por unanimidad. Cerveró ha sido gerente de la Orquesta Sinfónica de Valencia, director musical del Ballet de los Teatros de la Generalitat, responsable del programa Series 20/21 del propio CNDM y director de Música del Institut Valencià de Cultura. Según Ritmo, 1 de octubre.", "etiquetas": ["instituciones", "inaem", "cndm", "nombramientos"], "pais": "ES", "anio": "2026", "obras": [], "personas": [], "comp": [{"t": "nocons", "txt": "La Zarzuteca recoge autores históricos y no gestores en activo, de modo que no hay ficha que enlazar. Tampoco consta en nuestras fuentes a quién sustituye en el cargo.", "ficha": null}]}, {"id": "2026-09-30-bravura-arias-maria-mayor-ordonez", "fecha": "2026-09-30", "medio": "Melómano", "url": "https://www.melomanodigital.com/resena-bravura-arias-para-maria-mayor-ordonez-la-mayorita/", "titulo": "Un disco reúne arias de zarzuela barroca escritas para la cantante María Mayor Ordóñez", "texto": "El sello Tendresa Records publica «Bravura. Arias para María Mayor Ordóñez, la Mayorita», con la soprano Aurora Peña, la Orquesta La Festería y la dirección de Jordi Domènech. El programa reúne oberturas y arias de zarzuelas españolas de la década de 1770 —«El buen marido», «El amor en la aldea» y «Escipión en Cartagena»— y la tonadilla «El chasco del usía», con música de García Pacheco, Castel y Antonio Rodríguez de Hita. Melómano califica la grabación de lectura excepcional. Según Melómano, 30 de septiembre.", "etiquetas": ["grabación", "discografía", "barroco", "recuperacion"], "pais": "ES", "anio": "2026", "obras": [], "personas": [{"id": "antonio-rodriguez-de-hita", "n": "Antonio Rodríguez de Hita"}], "comp": [{"t": "consta", "txt": "Antonio Rodríguez de Hita tiene ficha en la Zarzuteca.", "ficha": null}, {"t": "aporta", "txt": "De Antonio Rodríguez de Hita este archivo recoge «Las labradoras de Murcia», estrenada el 16 de septiembre de 1769.", "ficha": {"tipo": "persona", "id": "antonio-rodriguez-de-hita", "n": "Antonio Rodríguez de Hita"}}, {"t": "nocons", "txt": "Las cuatro obras del disco no constan todavía en este archivo, ni los compositores citados como García Pacheco y Castel, ni la propia cantante María Mayor Ordóñez. No consta en nuestras fuentes la fecha ni el teatro del estreno de ninguna de ellas.", "ficha": null}, {"t": "nocons", "txt": "La fuente es una reseña con valoración del medio. Los datos del disco no constan contrastados con el catálogo del sello.", "ficha": null}]}, {"id": "2026-09-29-residencia-zarzuela-fundacion-placido-domingo", "fecha": "2026-09-29", "medio": "Ópera Actual", "url": "https://www.operaactual.com/critica/primera-edicion-de-la-residencia-de-zarzuela-de-la-fundacion-placido-domingo/", "titulo": "La Fundación Plácido Domingo celebra la primera edición de su Residencia de Zarzuela", "texto": "La Fundación Plácido Domingo celebró entre el 21 y el 26 de septiembre, en la Escuela Superior de Canto de Madrid, la primera edición de su Residencia de Zarzuela, con clases magistrales de Óliver Díaz, Nancy Fabiola Herrera, Carlos Álvarez y Emilio Sagi. Participaron nueve cantantes de siete países procedentes de Operalia. El concierto final, en el Teatro del Palacio Bauer, lo dirigió Óliver Díaz al frente de la Orquesta Clásica Santa Cecilia, con páginas de Serrano, Moreno Torroba, Soutullo y Vert, Chapí, Sorozábal, Vives, Nieto y Giménez y Luna. Según Ópera Actual, 29 de septiembre.", "etiquetas": ["instituciones", "interpretes", "concierto"], "pais": "ES", "anio": "2026", "obras": [{"id": "la-dolorosa", "t": "La Dolorosa"}, {"id": "la-marchenera", "t": "La marchenera"}, {"id": "la-del-soto-del-parral", "t": "La del Soto del Parral"}, {"id": "las-hijas-del-zebedeo", "t": "Las hijas del Zebedeo"}, {"id": "el-barquillero", "t": "El barquillero"}, {"id": "luisa-fernanda", "t": "Luisa Fernanda"}, {"id": "el-barbero-de-sevilla", "t": "El barbero de Sevilla"}, {"id": "dona-francisquita", "t": "Doña Francisquita"}, {"id": "la-tabernera-del-puerto", "t": "La tabernera del puerto"}], "personas": [{"id": "jose-serrano", "n": "José Serrano"}, {"id": "federico-moreno-torroba", "n": "Federico Moreno Torroba"}, {"id": "reveriano-soutullo", "n": "Reveriano Soutullo"}, {"id": "juan-vert", "n": "Juan Vert"}, {"id": "ruperto-chapi", "n": "Ruperto Chapí"}, {"id": "amadeo-vives", "n": "Amadeo Vives"}, {"id": "pablo-sorozabal", "n": "Pablo Sorozábal"}, {"id": "manuel-nieto", "n": "Manuel Nieto"}, {"id": "geronimo-gimenez", "n": "Gerónimo Giménez"}, {"id": "pablo-luna", "n": "Pablo Luna"}], "comp": [{"t": "consta", "txt": "Nueve de las obras del concierto final y los diez compositores citados tienen ficha en la Zarzuteca.", "ficha": null}, {"t": "aporta", "txt": "«Las hijas del Zebedeo», de Ruperto Chapí, se estrenó el 9 de julio de 1889 en el Teatro Maravillas de Madrid, con libreto de José Estremera.", "ficha": {"tipo": "obra", "id": "las-hijas-del-zebedeo", "n": "Las hijas del Zebedeo"}}, {"t": "aporta", "txt": "«El barbero de Sevilla» de Manuel Nieto y Gerónimo Giménez, que no debe confundirse con la ópera de Rossini, se estrenó el 5 de febrero de 1901 en el Teatro de la Zarzuela de Madrid.", "ficha": {"tipo": "obra", "id": "el-barbero-de-sevilla", "n": "El barbero de Sevilla"}}, {"t": "nocons", "txt": "Dos obras del programa no tienen todavía ficha en este archivo: «Maravilla», de Federico Moreno Torroba, y «La pícara molinera», de Pablo Luna, aunque sus dos compositores sí la tienen.", "ficha": null}, {"t": "nocons", "txt": "La fuente escribe varios nombres de cantantes de dos maneras distintas en el mismo texto, por lo que esta nota no los recoge. No consta en nuestras fuentes si la Residencia tendrá continuidad anual.", "ficha": null}]}, {"id": "2026-09-28-villamarta-falla-amor-brujo-vida-breve", "fecha": "2026-09-28", "medio": "Ópera Actual", "url": "https://www.operaactual.com/noticia/el-villamarta-inaugura-su-temporada-lirica-con-el-universo-de-falla/", "titulo": "El Teatro Villamarta abre su temporada lírica con un programa doble de Falla por su 150º aniversario", "texto": "El Teatro Villamarta de Jerez de la Frontera inaugura su temporada lírica los días 2 y 4 de octubre con una nueva producción que reúne el ballet «El amor brujo» y la ópera «La vida breve», de Manuel de Falla, dentro de las celebraciones por el 150º aniversario de su nacimiento. Carlos Domínguez-Nieto dirige la Orquesta Bética de Sevilla y Carlos Roó firma la escena. Cantan Maribel Ortega como Salud y Antoni Lliteres como Paco; Eduardo Guerrero es el Espectro y firma la coreografía. Según Ópera Actual, 28 de septiembre.", "etiquetas": ["opera-espanola", "temporada", "aniversario"], "pais": "ES", "anio": "2026", "obras": [{"id": "el-amor-brujo", "t": "El amor brujo"}, {"id": "la-vida-breve", "t": "La vida breve"}], "personas": [{"id": "manuel-de-falla", "n": "Manuel de Falla"}], "comp": [{"t": "consta", "txt": "Manuel de Falla, «La vida breve» y «El amor brujo» tienen ficha en la Zarzuteca.", "ficha": null}, {"t": "nocons", "txt": "El 150º aniversario del nacimiento del compositor como marco de la producción solo lo afirma esta fuente; no consta contrastado en nuestras fuentes.", "ficha": null}, {"t": "nocons", "txt": "El tenor Antoni Lliteres no debe confundirse con el compositor Antoni Literes: son dos personas distintas. Literes aún no tiene ficha en la Zarzuteca.", "ficha": null}]}, {"id": "2026-09-28-cndm-record-abonados-jupiter-y-calisto", "fecha": "2026-09-28", "medio": "Ritmo", "url": "https://www.ritmo.es/actualidad/el-centro-nacional-de-difusion-musical-vuelve-a-batir-records-de-venta-de-abonos-y-localidades", "titulo": "El CNDM abre temporada con un récord de abonados y programa la recuperación de una zarzuela de Mele", "texto": "El Centro Nacional de Difusión Musical, unidad del INAEM, abre su temporada 26-27 con 6.014 personas abonadas, la cifra más alta de su historia, y más de 3.200 entradas vendidas en la primera semana. Entre sus estrenos figura la recuperación y el estreno en tiempos modernos de la zarzuela «Jupiter y Calisto», de Juan Bautista Mele, a cargo de Il Fervore y Jesús Merino, dentro del ciclo Universo Barroco Sinfónico. El Ciclo de Lied, en su 33ª edición, es coproducción del CNDM y el Teatro de la Zarzuela. Según Ritmo, 28 de septiembre.", "etiquetas": ["instituciones", "recuperacion", "patrimonio"], "pais": "ES", "anio": "2026", "obras": [], "personas": [], "comp": [{"t": "nocons", "txt": "Ni «Jupiter y Calisto» ni Juan Bautista Mele tienen ficha en la Zarzuteca. Es una obra que este archivo aún no recoge y cuya incorporación queda pendiente.", "ficha": null}, {"t": "nocons", "txt": "El título y el nombre del compositor se transcriben como los da el medio. No consta en nuestras fuentes la grafía que les dan los repertorios musicológicos, ni la fecha y el teatro del estreno original, ni la fecha del concierto del CNDM.", "ficha": null}]}, {"id": "2026-09-27-el-gato-montes-palau-valencia", "fecha": "2026-09-27", "medio": "Codalario", "url": "https://www.codalario.com/palau-de-la-musica-de-valencia/portada/el-gato-montes-en-el-palau-de-la-musica-de-valencia--con-antonio-gandia--maria-zapata-y-angel-odena_14966_2_49831_0_1_in.html", "titulo": "«El gato montés» de Penella se ofrece en versión de concierto en el Palau de la Música de Valencia", "texto": "El Palau de la Música de Valencia programa el 1 de octubre un concierto extraordinario con «El gato montés», de Manuel Penella, en versión de concierto. Cantan el tenor Antonio Gandía, el barítono Ángel Ódena, la soprano María Zapata, el bajo Rubén Amoretti, las mezzosopranos María Luisa Corbacho y Estíbaliz Ruiz y el bajo Pau Ferrer, entre otros. Rubén Sánchez dirige la Orquesta de Valencia, la Escolanía de Nuestra Señora de los Desamparados y la Coral Catedralicia de Valencia. Según Codalario, 27 de septiembre.", "etiquetas": ["opera-espanola", "concierto", "interpretes"], "pais": "ES", "anio": "2026", "obras": [{"id": "el-gato-montes", "t": "El gato montés"}], "personas": [{"id": "manuel-penella", "n": "Manuel Penella"}], "comp": [{"t": "consta", "txt": "La obra y su autor tienen ficha en la Zarzuteca.", "ficha": null}, {"t": "aporta", "txt": "«El gato montés», de Manuel Penella, se estrenó en Valencia, en el Teatro Principal, el 22 de febrero de 1917: el concierto la devuelve a la ciudad donde se vio por primera vez.", "ficha": {"tipo": "obra", "id": "el-gato-montes", "n": "El gato montés"}}, {"t": "aporta", "txt": "Manuel Penella firmó música y libreto de la obra, como recoge su ficha.", "ficha": {"tipo": "persona", "id": "manuel-penella", "n": "Manuel Penella"}}, {"t": "nocons", "txt": "No consta en nuestras fuentes si hay una sola función ni si la versión de concierto es producción propia del Palau. La grafía de los nombres de los intérpretes se recoge como la da el medio.", "ficha": null}]}, {"id": "2026-09-26-codalario-juguete-lirico-nuria-blanco", "fecha": "2026-09-26", "medio": "Codalario", "url": "https://www.codalario.com/zarzuela/portada/articulo-que-es-el-juguete-lirico.-por-nuria-blanco-alvarez_14964_2_49829_0_1_in.html", "titulo": "Codalario dedica la quinta entrega de su serie sobre el género chico al juguete lírico", "texto": "La quinta entrega de la serie de Codalario sobre el género chico, firmada por la musicóloga Nuria Blanco Álvarez, define el juguete lírico como zarzuela breve de ambiente burgués con un enredo amoroso resuelto felizmente, frente al casticismo del sainete. El artículo discute las características que Pilar Espín Templado atribuye al subgénero a partir de las veinticuatro obras así llamadas de Manuel Fernández Caballero, y propone «Chateau Margaux» y «La viejecita» como sus dos modelos. Según Codalario, 26 de septiembre.", "etiquetas": ["genero-chico", "divulgacion", "publicaciones"], "pais": "ES", "anio": "2026", "obras": [{"id": "chateau-margaux", "t": "Chateau-Margaux"}, {"id": "la-viejecita", "t": "La viejecita"}, {"id": "a-que-no-puedo-casarme", "t": "¿A que no puedo casarme?"}, {"id": "los-sobrinos-del-capitan-grant", "t": "Los sobrinos del capitán Grant"}], "personas": [{"id": "manuel-fernandez-caballero", "n": "Manuel Fernández Caballero"}, {"id": "jose-jackson-veyan", "n": "José Jackson Veyán"}, {"id": "francisco-asenjo-barbieri", "n": "Francisco Asenjo Barbieri"}, {"id": "cristobal-oudrid", "n": "Cristóbal Oudrid"}], "comp": [{"t": "consta", "txt": "Cuatro de las obras que cita el artículo y cuatro de los autores que menciona tienen ficha en la Zarzuteca.", "ficha": null}, {"t": "aporta", "txt": "«Chateau Margaux», con libreto de José Jackson Veyán, se estrenó el 5 de octubre de 1887 en el Teatro Variedades de Madrid, como recoge su ficha y sin discrepancia con la fuente.", "ficha": {"tipo": "obra", "id": "chateau-margaux", "n": "Chateau-Margaux"}}, {"t": "aporta", "txt": "«La viejecita» se estrenó el 30 de abril de 1897 en el Teatro de la Zarzuela de Madrid.", "ficha": {"tipo": "obra", "id": "la-viejecita", "n": "La viejecita"}}, {"t": "nocons", "txt": "Doce títulos más de juguetes de Manuel Fernández Caballero que cita el artículo no constan todavía en este archivo, entre ellos «La víspera de la fiesta», «Los rábanos por las hojas», «La magia negra» y «Don Jaime el conquistador». Tampoco tienen ficha los musicólogos citados, porque la Zarzuteca recoge autores históricos.", "ficha": null}]}, {"id": "2026-09-25-cambridge-history-music-in-spain", "fecha": "2026-09-25", "medio": "Ritmo", "url": "https://www.ritmo.es/actualidad/novedad-libros-music-in-spain-mil-anos-de-musica-espanola-del-canto-medieval-a-rosalia", "titulo": "Una historia de la música española de Cambridge dedica un capítulo a la zarzuela", "texto": "«The Cambridge History of Music in Spain», coordinada por Walter Aaron Clark, Ana Llorens y Álvaro Torrente y publicada por Cambridge University Press, se presentó el 22 de septiembre en el Museo Nacional del Prado con la colaboración del Instituto Complutense de Ciencias Musicales. La obra recorre la música española desde el siglo VI y dedica uno de sus trece capítulos temáticos a la zarzuela, firmado por Enrique Mejías García y Víctor Sánchez Sánchez. Según Ritmo, 25 de septiembre.", "etiquetas": ["publicaciones", "patrimonio", "instituciones"], "pais": "ES", "anio": "2026", "obras": [], "personas": [], "comp": [{"t": "nocons", "txt": "Los coordinadores y los autores del capítulo de zarzuela son musicólogos en activo, y el catálogo de la Zarzuteca solo recoge autores históricos: la noticia no enlaza ninguna ficha.", "ficha": null}, {"t": "nocons", "txt": "No se han verificado los datos editoriales del volumen —páginas, precio ni si habrá edición en castellano—, que la fuente no da.", "ficha": null}]}, {"id": "2026-09-22-la-del-manojo-de-rosas-concepcion-chile", "fecha": "2026-09-22", "medio": "Ópera Latinoamérica", "url": "https://www.operala.org/zarzuela-la-del-manojo-de-rosas-teatro-udec/", "titulo": "«La del manojo de rosas» se representa en Concepción en una coproducción chileno-colombiana", "texto": "El Teatro de la Universidad de Concepción programa el 2 de octubre «La del manojo de rosas», de Pablo Sorozábal, en una coproducción del propio teatro, Corcudec, con la Fundación Prolírica de Antioquia, de Colombia. La soprano Gisela Zivic canta Ascensión y firma además la dirección de escena; completan el reparto principal el barítono Juan Salvador Trupia y el tenor Julio Isaac. Juan Pablo Aguayo dirige la Orquesta Sinfónica de la Universidad de Concepción. Según Ópera Latinoamérica, 22 de septiembre.", "etiquetas": ["zarzuela", "internacional", "companias"], "pais": "CL", "anio": "2026", "obras": [{"id": "la-del-manojo-de-rosas", "t": "La del manojo de rosas"}], "personas": [{"id": "pablo-sorozabal", "n": "Pablo Sorozábal"}, {"id": "francisco-ramos-de-castro", "n": "Francisco Ramos de Castro"}, {"id": "anselmo-cuadrado-carreno", "n": "Anselmo Cuadrado Carreño"}], "comp": [{"t": "consta", "txt": "La obra y sus tres autores tienen ficha en la Zarzuteca.", "ficha": null}, {"t": "aporta", "txt": "«La del manojo de rosas», sainete lírico de Pablo Sorozábal sobre libreto de Francisco Ramos de Castro y Anselmo Cuadrado Carreño, se estrenó en el Teatro Fuencarral de Madrid el 13 de noviembre de 1934.", "ficha": {"tipo": "obra", "id": "la-del-manojo-de-rosas", "n": "La del manojo de rosas"}}, {"t": "consta", "txt": "El año y el teatro del estreno que da la fuente coinciden con los de la ficha del catálogo.", "ficha": null}]}, {"id": "2026-09-20-sainete-lirico-serie-nuria-blanco", "fecha": "2026-09-20", "medio": "Codalario", "url": "https://www.codalario.com/sainete-lirico/apartado-para-rotacion-de-informaciones-en-la-cabecera/articulo-que-es-el-sainete-lirico-por-nuria-blanco-alvarez_14951_34_49778_0_1_in.html", "titulo": "La serie de Codalario sobre el género chico dedica su cuarta entrega al sainete lírico", "texto": "La serie de Nuria Blanco Álvarez sobre el género chico publica en Codalario su entrega dedicada al sainete lírico, que define como zarzuela breve en un acto, de acción contemporánea, ambiente madrileño y final feliz. El artículo sitúa el nacimiento del género en «La canción de la Lola», de Federico Chueca y Joaquín Valverde con libreto de Ricardo de la Vega, estrenada en 1880, y recorre el paso del libreto en verso a la prosa a través de «La Gran Vía», «La revoltosa» y «La verbena de la Paloma». Según Codalario, 20 de septiembre.", "etiquetas": ["genero-chico", "divulgacion", "publicaciones"], "pais": "ES", "anio": "2026", "obras": [{"id": "la-cancion-de-la-lola", "t": "La canción de la Lola"}, {"id": "la-gran-via", "t": "La Gran Vía"}, {"id": "la-revoltosa", "t": "La revoltosa"}, {"id": "agua-azucarillos-y-aguardiente", "t": "Agua, azucarillos y aguardiente"}, {"id": "el-bateo", "t": "El bateo"}, {"id": "el-baile-de-luis-alonso", "t": "El baile de Luis Alonso"}, {"id": "la-verbena-de-la-paloma", "t": "La verbena de la Paloma"}], "personas": [{"id": "federico-chueca", "n": "Federico Chueca"}, {"id": "joaquin-valverde-duran", "n": "Joaquín Valverde Durán"}, {"id": "ricardo-de-la-vega", "n": "Ricardo de la Vega"}, {"id": "ramon-de-la-cruz", "n": "Ramón de la Cruz"}, {"id": "serafin-alvarez-quintero", "n": "Serafín Álvarez Quintero"}, {"id": "joaquin-alvarez-quintero", "n": "Joaquín Álvarez Quintero"}], "comp": [{"t": "consta", "txt": "Las siete obras que cita el artículo y seis de las personas nombradas tienen ficha en la Zarzuteca.", "ficha": null}, {"t": "aporta", "txt": "«La canción de la Lola», de Federico Chueca y Joaquín Valverde Durán sobre libreto de Ricardo de la Vega, se estrenó en el Teatro de la Alhambra de Madrid el 25 de mayo de 1880.", "ficha": {"tipo": "obra", "id": "la-cancion-de-la-lola", "n": "La canción de la Lola"}}, {"t": "aporta", "txt": "El Valverde de esta obra es Joaquín Valverde Durán, el padre. En el catálogo figura también su hijo, Joaquín Valverde Sanjuán, «Quinito», que no interviene en ella.", "ficha": {"tipo": "persona", "id": "joaquin-valverde-duran", "n": "Joaquín Valverde Durán"}}, {"t": "nocons", "txt": "El catálogo atribuye «Agua, azucarillos y aguardiente» y «El bateo» solo a Federico Chueca, sin Valverde. Por eso la nota cita esas obras sin atribuir su autoría.", "ficha": null}]}, {"id": "2026-09-20-especial-ola-compositores-mas-programados", "fecha": "2026-09-20", "medio": "Ópera Actual", "url": "https://www.operaactual.com/noticia/el-especial-la-temporada-lirica-de-ola-2026-supera-las-100-000-visitas/", "titulo": "Barbieri, Bretón y Penella figuran entre los quince compositores más programados del curso lírico iberoamericano de 2026", "texto": "Ópera Actual informa de que el especial «La temporada lírica de OLA 2026», editado con la Asociación Ópera Latinoamérica en digital y en abierto, ha superado los cien mil visitantes. La edición incorpora un artículo de Fernando Sans Rivière con dos cuadros estadísticos del repertorio programado en 2026 en Latinoamérica, España y Portugal: 127 títulos en 776 funciones. Entre los quince compositores más programados figuran Barbieri, Hidalgo, Bretón, Penella y Falla. Según Ópera Actual, 20 de septiembre.", "etiquetas": ["publicaciones", "temporada", "instituciones"], "pais": "INT", "anio": "2026", "obras": [], "personas": [{"id": "francisco-asenjo-barbieri", "n": "Francisco Asenjo Barbieri"}, {"id": "tomas-breton", "n": "Tomás Bretón"}, {"id": "manuel-penella", "n": "Manuel Penella"}], "comp": [{"t": "consta", "txt": "Tres de los cinco compositores españoles que cita la fuente tienen ficha en la Zarzuteca: Barbieri, Bretón y Penella.", "ficha": null}, {"t": "nocons", "txt": "Juan Hidalgo y Manuel de Falla no figuran en el catálogo publicado, por lo que la nota los nombra sin enlace a ficha.", "ficha": null}, {"t": "nocons", "txt": "La fuente no desglosa cuántas de las 776 funciones son de zarzuela. El podio de compositores lo ocupan Verdi, Puccini, Mozart, Wagner y Gounod; los nombres españoles están en el grupo de quince, no en el podio.", "ficha": null}]}, {"id": "2026-09-20-andromeda-y-perseo-calderon-juan-hidalgo", "fecha": "2026-09-20", "medio": "Ritmo", "url": "https://www.ritmo.es/actualidad/la-fundacion-juan-march-el-teatro-de-la-zarzuela-y-la-compania-nacional-de-teatro-clasico-recuperan-una-joya-musical-de-calderon-y-juan-hidalgo", "titulo": "«Andrómeda y Perseo», de Calderón y Juan Hidalgo, vuelve a escena en una coproducción de la Fundación Juan March, el Teatro de la Zarzuela y la CNTC", "texto": "La Fundación Juan March, el Teatro de la Zarzuela y la Compañía Nacional de Teatro Clásico coproducen la recuperación de «Andrómeda y Perseo», fábula mitológica con libreto de Pedro Calderón de la Barca y música atribuida a Juan Hidalgo, que no se representa desde su estreno en 1653. La Fundación Juan March ofrece seis funciones gratuitas del 30 de septiembre al 10 de octubre, con retransmisión en línea el 7, y el Teatro de la Comedia otras nueve del 4 al 13 de diciembre. Dirigen Aarón Zapico y Nuria Castejón. Según Ritmo, 20 de septiembre.", "etiquetas": ["recuperacion", "patrimonio", "instituciones"], "pais": "ES", "anio": "2026", "obras": [], "personas": [{"id": "pedro-calderon-de-la-barca", "n": "Pedro Calderón de la Barca"}], "comp": [{"t": "consta", "txt": "Pedro Calderón de la Barca tiene ficha de libretista en la Zarzuteca.", "ficha": {"tipo": "persona", "id": "pedro-calderon-de-la-barca", "n": "Pedro Calderón de la Barca"}}, {"t": "nocons", "txt": "Ni «Andrómeda y Perseo» ni el compositor Juan Hidalgo figuran en el catálogo publicado, por lo que la nota los nombra sin enlace a ficha.", "ficha": null}, {"t": "nocons", "txt": "La fecha de 1653 la da el medio que trata la noticia en detalle; otro medio dice solo «siglo XVII». El dato no se ha contrastado en fuente académica.", "ficha": null}]}, {"id": "2026-09-18-verbena-paloma-abre-temporada-zarzuela", "fecha": "2026-09-18", "medio": "Codalario", "url": "https://www.codalario.com/la-verbena-de-la-paloma/portada/la-verbena-de-la-paloma-inaugura-la-temporada-2026-27-del-teatro-de-la-zarzuela_14948_2_49780_0_1_in.html", "titulo": "El Teatro de la Zarzuela abre el 23 de septiembre con «La verbena de la Paloma» y el prólogo «Adiós, Apolo»", "texto": "El Teatro de la Zarzuela inaugura su temporada 2026-2027 el 23 de septiembre con «La verbena de la Paloma», de Tomás Bretón y Ricardo de la Vega, en la producción de 2024 de la propia casa, precedida del prólogo cómico-lírico «Adiós, Apolo», con texto de Álvaro Tato. Carlos Aragón dirige la Orquesta de la Comunidad de Madrid y Nuria Castejón firma la escena. Borja Quiza y César San Martín alternan el papel de Julián. Son diez funciones, hasta el 4 de octubre. Según Codalario y Ritmo, 18 de septiembre.", "etiquetas": ["temporada", "instituciones", "estreno"], "pais": "ES", "anio": "2026", "obras": [{"id": "la-verbena-de-la-paloma", "t": "La verbena de la Paloma"}], "personas": [{"id": "tomas-breton", "n": "Tomás Bretón"}, {"id": "ricardo-de-la-vega", "n": "Ricardo de la Vega"}], "comp": [{"t": "consta", "txt": "La obra y sus dos autores tienen ficha en la Zarzuteca.", "ficha": null}, {"t": "aporta", "txt": "«La verbena de la Paloma», sainete lírico de Tomás Bretón sobre libreto de Ricardo de la Vega, se estrenó en el Teatro Apolo de Madrid el 17 de febrero de 1894.", "ficha": {"tipo": "obra", "id": "la-verbena-de-la-paloma", "n": "La verbena de la Paloma"}}, {"t": "aporta", "txt": "Ficha artística, reparto y calendario se han contrastado con la programación publicada por el propio Teatro de la Zarzuela, que es la fuente oficial.", "ficha": null}, {"t": "nocons", "txt": "Un medio llama «Jorge» al personaje protagonista. El nombre que constan el libreto y la ficha oficial del teatro es Julián, y es el que usa esta nota.", "ficha": null}]}, {"id": "2026-09-15-chorizos-y-polacos-150-anios", "fecha": "2026-09-15", "medio": "Melómano", "url": "https://www.melomanodigital.com/150-aniversario-del-estreno-de-chorizos-y-polacos-de-barbieri/", "titulo": "Un reportaje de Melómano repasa los ciento cincuenta años de «Chorizos y polacos», de Barbieri", "texto": "Melómano dedica un reportaje de Rebeca Barriuso González a los ciento cincuenta años de «Chorizos y polacos», zarzuela en tres actos de Francisco Asenjo Barbieri con libreto de Luis Mariano de Larra, estrenada el 24 de mayo de 1876 en el Teatro del Príncipe Alfonso de Madrid. El texto recuerda que la obra lleva a la escena la rivalidad entre las dos facciones de aficionados del teatro madrileño del siglo XVIII y que alcanzó treinta representaciones entre 1876 y 1878. Según Melómano, 15 de septiembre.", "etiquetas": ["aniversario", "patrimonio", "compositores"], "pais": "ES", "anio": "2026", "obras": [{"id": "chorizos-y-polacos", "t": "Chorizos y polacos"}], "personas": [{"id": "francisco-asenjo-barbieri", "n": "Francisco Asenjo Barbieri"}, {"id": "luis-mariano-de-larra-y-wetoret", "n": "Luis Mariano de Larra y Wetoret"}], "comp": [{"t": "consta", "txt": "La obra y sus dos autores tienen ficha en la Zarzuteca, y la fecha y el teatro del estreno coinciden con los que da el medio.", "ficha": {"tipo": "obra", "id": "chorizos-y-polacos", "n": "Chorizos y polacos"}}, {"t": "aporta", "txt": "El libretista es Luis Mariano de Larra y Wetoret, hijo de Mariano José de Larra. En el catálogo hay otro Larra libretista, Luis de Larra y Ossorio, que no es el de esta obra.", "ficha": {"tipo": "persona", "id": "luis-mariano-de-larra-y-wetoret", "n": "Luis Mariano de Larra y Wetoret"}}, {"t": "nocons", "txt": "El aniversario se cumplió el 24 de mayo de 2026; el reportaje se publica después. El texto no anuncia ningún acto, concierto ni edición conmemorativa.", "ficha": null}]}, {"id": "2026-09-11-breton-canciones-trios-ibs", "fecha": "2026-09-11", "medio": "Scherzo", "url": "https://scherzo.es/breton-becquer-y-musica-de-camara/", "titulo": "IBS Classical publica en doble CD las canciones y los tríos con piano de Tomás Bretón", "texto": "El sello IBS Classical ha editado en dos discos las canciones y los tríos con piano de Tomás Bretón, con la soprano Natalia Labourdette, la pianista Victoria Guerrero, el violinista Carles Civera y el violonchelista Alejandro Olóriz. Scherzo publicó el 11 de septiembre la crítica de Andrés Moreno Mengibar, para quien la difusión de la música de Bretón ajena a sus zarzuelas y sainetes revela la calidad de su escritura; el crítico recuerda que el compositor renegó de buena parte de aquel repertorio por considerarlo trabajo alimenticio.", "etiquetas": ["grabación", "discografía", "siglo XIX"], "pais": "ES", "anio": "2026", "obras": [], "personas": [{"id": "tomas-breton", "n": "Tomás Bretón"}], "comp": [{"t": "consta", "txt": "Tomás Bretón tiene ficha en la Zarzuteca, con doble condición de compositor y libretista.", "ficha": null}, {"t": "aporta", "txt": "El catálogo publica cinco obras suyas como compositor —«Al fin se casa la Nieves», «Covadonga», «La Dolores», «La verbena de la Paloma» y «Los amores de un príncipe»— y de «La Dolores», estrenada en 1895 en el Teatro de la Zarzuela, firmó además el libreto sobre el drama de Feliu y Codina.", "ficha": {"tipo": "persona", "id": "tomas-breton", "n": "Tomás Bretón"}}, {"t": "nocons", "txt": "El repertorio concreto del disco no consta en nuestras fuentes: la crítica de Scherzo solo se lee entera con suscripción y el fragmento en abierto no detalla las obras ni el año de edición. Por eso no se enlaza ninguna ficha de obra.", "ficha": null}]}, {"id": "2026-09-10-oa-especial-temporada-lirica-2026-27", "fecha": "2026-09-10", "medio": "Ópera Actual", "url": "https://www.operaactual.com/noticia/opera-actual-y-opera-xxi-presentan-el-especial-temporada-lirica-2026-27/", "titulo": "Ópera Actual y Ópera XXI publican en abierto el calendario lírico español de la temporada 2026-27", "texto": "Ópera Actual edita con la asociación Ópera XXI un especial de acceso libre con la temporada lírica española 2026-27: 98 títulos, 526 funciones escenificadas y 29 en versión de concierto. En el recuento de su director, Fernando Sans Rivière, trece de los treinta compositores más programados son españoles, encabezados por Barbieri, Hidalgo y Martínez Valls, y «La verbena de la Paloma» es la zarzuela más representada, con catorce funciones. El Teatro de la Zarzuela, que cumple 170 años, sigue siendo el principal escenario del género. Según Ópera Actual, 10 de septiembre.", "etiquetas": ["temporada", "revista", "instituciones"], "pais": "ES", "anio": "2026", "obras": [{"id": "la-verbena-de-la-paloma", "t": "La verbena de la Paloma"}, {"id": "el-barberillo-de-lavapies", "t": "El barberillo de Lavapiés"}, {"id": "la-bruja", "t": "La bruja"}, {"id": "los-gavilanes", "t": "Los gavilanes"}, {"id": "el-duo-de-la-africana", "t": "El dúo de La africana"}, {"id": "la-tabernera-del-puerto", "t": "La tabernera del puerto"}, {"id": "luisa-fernanda", "t": "Luisa Fernanda"}, {"id": "el-gato-montes", "t": "El gato montés"}, {"id": "jugar-con-fuego", "t": "Jugar con fuego"}, {"id": "katiuska", "t": "Katiuska"}, {"id": "luna-de-miel-en-el-cairo", "t": "Luna de miel en El Cairo"}], "personas": [{"id": "tomas-breton", "n": "Tomás Bretón"}, {"id": "francisco-asenjo-barbieri", "n": "Francisco Asenjo Barbieri"}, {"id": "ruperto-chapi", "n": "Ruperto Chapí"}, {"id": "jacinto-guerrero", "n": "Jacinto Guerrero"}, {"id": "manuel-fernandez-caballero", "n": "Manuel Fernández Caballero"}, {"id": "pablo-sorozabal", "n": "Pablo Sorozábal"}, {"id": "federico-moreno-torroba", "n": "Federico Moreno Torroba"}, {"id": "manuel-penella", "n": "Manuel Penella"}, {"id": "francisco-alonso", "n": "Francisco Alonso"}], "comp": [{"t": "consta", "txt": "Once de los títulos del repertorio hispano que programa la temporada tienen ficha en la Zarzuteca, con las funciones que les cuenta el especial: «La verbena de la Paloma» (14), «El barberillo de Lavapiés», «La bruja» y «Los Gavilanes» (13 cada una), «El dúo de La Africana» (5), «La tabernera del puerto» y «Luisa Fernanda» (3), y «El Gato Montés», «Jugar con fuego», «Katiuska» y «Luna de miel en El Cairo» (2 cada una).", "ficha": null}, {"t": "aporta", "txt": "El Teatro de la Zarzuela, cuyo aniversario abre el especial, es el segundo escenario con más estrenos de la Zarzuteca, solo por detrás del Teatro Apolo: sesenta y tres de las obras publicadas se estrenaron allí, desde 1857 —«Los Magyares», de Joaquín Gaztambide, y «El Relámpago», de Francisco Asenjo Barbieri— hasta 1928, con «La Marchenera», de Federico Moreno Torroba, y «Martierra», de Jacinto Guerrero.", "ficha": {"tipo": "obra", "id": "los-magyares", "n": "Los magyares"}}, {"t": "nocons", "txt": "Otros títulos hispanos del calendario no constan todavía en el catálogo publicado: «Andrómeda y Perseo», de Hidalgo, y «Venus y Adonis», de Nebra, del repertorio antiguo; «Cançó d'amor i de guerra», de Martínez Valls, cuyo estreno cumple cien años; «El amor brujo» y «La vida breve», de Falla; y los estrenos y obras recientes «Poeta en Nueva York», de Carretero, «Las trece rosas rojas», de Bercovich, «Bodas de sangre», de Manuel Busto, y «El orgullo de quererte», de Carmena.", "ficha": null}, {"t": "nocons", "txt": "Las cifras son del propio medio, tomadas del recuento que firma su director, y no se han cotejado función por función. La efeméride de los 170 años también es suya: nuestras fichas de teatros no guardan la fecha de apertura.", "ficha": null}]}, {"id": "2026-09-09-los-elementos-literes-festival-contratemps", "fecha": "2026-09-09", "medio": "Ópera Actual", "url": "https://www.operaactual.com/noticia/el-festival-contratemps-programa-la-opera-los-elementos-de-literes/", "titulo": "El Festival Contratemps clausura su octava edición con «Los Elementos» de Antonio Literes", "texto": "El Festival Contratemps, dedicado a las músicas históricas en Sant Cugat del Vallès y Terrassa, clausura su octava edición el 3 de octubre con «Los Elementos», de Antonio Literes, en el claustro del monasterio de Sant Cugat. Interviene el Ensemble Contratemps, con las sopranos Aurora Peña y Violeta Alarcón, las mezzosopranos Helena Ressurreição y Marta Valero, el tenor Jorge Juan Morata y los bailarines flamencos Esmeralda Manzanas y Miguel Lara. El festival se extiende del 5 de septiembre al 3 de octubre, según Ópera Actual.", "etiquetas": ["festival", "barroco"], "pais": "ES", "anio": "2026", "obras": [], "personas": [], "comp": [{"t": "nocons", "txt": "Ni Antonio Literes ni «Los Elementos» tienen todavía ficha en la Zarzuteca, de modo que esta noticia no enlaza con el catálogo. Las dos fichas están en nuestra lista de pendientes.", "ficha": null}, {"t": "nocons", "txt": "No consta en nuestras fuentes de qué dirección se hace cargo Adrián Schvarzstein. Ópera Actual escribe «Ensemble Contratemps, dirigido por Adrián Schvarzstein», mientras el programa de la producción lo presenta como actor y responsable de la dirección escénica. Por eso esta nota no le atribuye ninguna dirección.", "ficha": null}, {"t": "nocons", "txt": "El género de la obra tampoco consta de una sola manera: Ópera Actual la llama ópera barroca y la producción se anuncia como ópera flamenca. La nota se limita a nombrarla.", "ficha": null}, {"t": "nocons", "txt": "La función anunciada es única, el 3 de octubre en el monasterio de Sant Cugat. No consta en nuestras fuentes ninguna otra función de esta obra en Terrassa, aunque el festival se reparta entre las dos ciudades.", "ficha": null}]}, {"id": "2026-09-08-teatro-zarzuela-temporada-170-anios", "fecha": "2026-09-08", "medio": "Lanza Digital", "url": "https://www.lanzadigital.com/cultura/arranca-la-temporada-2026-27-del-teatro-de-la-zarzuela/", "titulo": "El Teatro de la Zarzuela abre la temporada de sus 170 años con «La verbena de la Paloma»", "texto": "El Teatro de la Zarzuela abre el 23 de septiembre la temporada 2026-2027, la de sus 170 años, con «La verbena de la Paloma», de Tomás Bretón, en cartel hasta el 4 de octubre. El programa lírico sigue con «Las trece rosas rojas», el 25 de noviembre; «Los gavilanes», de Jacinto Guerrero, el 28 de enero; «La bruja», de Ruperto Chapí, el 11 de marzo; «El dúo de la africana», de Manuel Fernández Caballero, el 10 de abril; «Venus y Adonis», el 5 de mayo, y «El barberillo de Lavapiés», de Barbieri, el 9 de junio. Según Lanza Digital y la programación publicada por el teatro.", "etiquetas": ["temporada", "instituciones", "aniversario"], "pais": "ES", "anio": "2026", "obras": [{"id": "la-verbena-de-la-paloma", "t": "La verbena de la Paloma"}, {"id": "los-gavilanes", "t": "Los gavilanes"}, {"id": "la-bruja", "t": "La bruja"}, {"id": "el-duo-de-la-africana", "t": "El dúo de La africana"}, {"id": "el-barberillo-de-lavapies", "t": "El barberillo de Lavapiés"}], "personas": [{"id": "tomas-breton", "n": "Tomás Bretón"}, {"id": "jacinto-guerrero", "n": "Jacinto Guerrero"}, {"id": "ruperto-chapi", "n": "Ruperto Chapí"}, {"id": "manuel-fernandez-caballero", "n": "Manuel Fernández Caballero"}, {"id": "francisco-asenjo-barbieri", "n": "Francisco Asenjo Barbieri"}], "comp": [{"t": "consta", "txt": "Las cinco zarzuelas de la temporada tienen ficha en la Zarzuteca, y también sus cinco autores.", "ficha": null}, {"t": "aporta", "txt": "«La verbena de la Paloma», sainete lírico de Tomás Bretón sobre libreto de Ricardo de la Vega, se estrenó en el Teatro Apolo de Madrid el 17 de febrero de 1894.", "ficha": {"tipo": "obra", "id": "la-verbena-de-la-paloma", "n": "La verbena de la Paloma"}}, {"t": "aporta", "txt": "«El Barberillo de Lavapiés», de Francisco Asenjo Barbieri, se estrenó el 18 de diciembre de 1874; «La Bruja», de Ruperto Chapí, el 10 de diciembre de 1887; «El Dúo de la Africana», de Manuel Fernández Caballero, el 13 de mayo de 1893, y «Los gavilanes», de Jacinto Guerrero, el 7 de diciembre de 1923.", "ficha": {"tipo": "obra", "id": "el-barberillo-de-lavapies", "n": "El barberillo de Lavapiés"}}, {"t": "nocons", "txt": "«Las trece rosas rojas» y «Venus y Adonis» no tienen ficha en el catálogo publicado y el listado oficial del teatro no da sus autores, por lo que la nota los nombra sin atribuir autoría.", "ficha": null}]}, {"id": "2026-09-07-soriano-gala-zarzuela", "fecha": "2026-09-07", "medio": "Ópera Actual", "url": "https://www.operaactual.com/noticia/el-otono-musical-soriano-inaugura-su-34a-edicion-con-una-gala-de-zarzuela/", "titulo": "El Otoño Musical Soriano abre su 34ª edición con una gala de zarzuela dirigida por Alondra de la Parra", "texto": "El Festival Otoño Musical Soriano inauguró su 34ª edición el 10 de septiembre con el programa «Todo Zarzuela», por la Orquesta y Coro de la Comunidad de Madrid con Alondra de la Parra, la mezzosoprano Carmen Artaza y el barítono Manel Esteve. Según Codalario, sonaron el preludio de «La verbena de la Paloma», el intermedio de «La boda de Luis Alonso», el coro de románticos de «Doña Francisquita» y la romanza «No corté más que una rosa» de «La del manojo de rosas», más un número de «El orgullo de quererte», de Javier Carmena. Lo informaron Ópera Actual y Codalario.", "etiquetas": ["concierto", "festival"], "pais": "ES", "anio": "2026", "obras": [{"id": "la-verbena-de-la-paloma", "t": "La verbena de la Paloma"}, {"id": "la-boda-de-luis-alonso", "t": "La boda de Luis Alonso"}, {"id": "dona-francisquita", "t": "Doña Francisquita"}, {"id": "la-del-manojo-de-rosas", "t": "La del manojo de rosas"}], "personas": [{"id": "tomas-breton", "n": "Tomás Bretón"}, {"id": "francisco-asenjo-barbieri", "n": "Francisco Asenjo Barbieri"}, {"id": "ruperto-chapi", "n": "Ruperto Chapí"}, {"id": "jacinto-guerrero", "n": "Jacinto Guerrero"}, {"id": "geronimo-gimenez", "n": "Gerónimo Giménez"}, {"id": "federico-moreno-torroba", "n": "Federico Moreno Torroba"}, {"id": "pablo-sorozabal", "n": "Pablo Sorozábal"}, {"id": "amadeo-vives", "n": "Amadeo Vives"}], "comp": [{"t": "consta", "txt": "Las cuatro zarzuelas cuyas páginas detalla Codalario tienen ficha en la Zarzuteca: «La verbena de la Paloma», de Tomás Bretón (1894); «La boda de Luis Alonso», de Gerónimo Giménez (1897); «Doña Francisquita», de Amadeo Vives (1923); y «La del manojo de rosas», de Pablo Sorozábal (1934). Los ocho compositores del programa tienen también la suya.", "ficha": null}, {"t": "aporta", "txt": "«La boda de Luis Alonso» y «Doña Francisquita» se estrenaron en los dos teatros que más estrenos reúnen en el catálogo: la primera en el Teatro de la Zarzuela, el 27 de enero de 1897, y la segunda en el Apolo, el 17 de octubre de 1923.", "ficha": {"tipo": "obra", "id": "la-boda-de-luis-alonso", "n": "La boda de Luis Alonso"}}, {"t": "nocons", "txt": "Codalario enumera en su propio texto a «Bretón, Chapí, Guerrero, Alonso, Vives y Sorozábal», mientras que la cita del festival que recoge en el mismo artículo dice «Bretón, Barbieri, Chapí, Guerrero, Moreno Torroba, Vives, Giménez o Sorozábal». Nuestras fuentes dan «La boda de Luis Alonso» a Gerónimo Giménez, no a Francisco Alonso, así que no se enlaza la ficha de Alonso.", "ficha": null}, {"t": "nocons", "txt": "«El orgullo de quererte», de Javier Carmena, estrenada en 2022 en los Teatros del Canal según Codalario, no consta en el catálogo publicado: la Zarzuteca no llega todavía al repertorio de estreno reciente.", "ficha": null}]}, {"id": "2026-09-06-rosa-azafran-kiev", "fecha": "2026-09-06", "medio": "Scherzo", "url": "https://scherzo.es/se-estrena-the-safron-rose-documental-sobre-la-zarzuela-de-guerrero-en-kiev/", "titulo": "Un documental sigue el montaje de «La rosa del azafrán» en el Teatro Nacional de Opereta de Kiev", "texto": "El cortometraje documental The Safron Rose se estrena el 16 de septiembre en los Cines Zoco de Majadahonda, con un coloquio dirigido por Ignacio García, director de escena y promotor del proyecto. La película, de 29 minutos, se rodó en Kiev a finales de 2024 y sigue la preparación y el estreno de La rosa del azafrán, de Jacinto Guerrero, en el Teatro Nacional de Opereta de Ucrania. Es una producción hispano-ucraniana de La Máquina de Luz, con la Fundación Jacinto e Inocencio Guerrero y la Embajada de España en Ucrania.", "etiquetas": ["documental", "patrimonio", "internacional"], "pais": "ES", "anio": "2026", "obras": [{"id": "la-rosa-del-azafran", "t": "La rosa del azafrán"}], "personas": [{"id": "jacinto-guerrero", "n": "Jacinto Guerrero"}, {"id": "federico-romero", "n": "Federico Romero"}, {"id": "guillermo-fernandez-shaw-iturralde", "n": "Guillermo Fernández-Shaw Iturralde"}], "comp": [{"t": "consta", "txt": "La rosa del azafrán, con música de Jacinto Guerrero y libreto de Federico Romero y Guillermo Fernández-Shaw, consta así en el catálogo.", "ficha": null}, {"t": "aporta", "txt": "Se estrenó el 14 de marzo de 1930 en el Teatro Calderón de Madrid.", "ficha": {"tipo": "obra", "id": "la-rosa-del-azafran", "n": "La rosa del azafrán"}}, {"t": "nocons", "txt": "El documental, su rodaje y su estreno son actualidad y quedan fuera del archivo: no se han podido contrastar aquí.", "ficha": null}]}, {"id": "2026-09-06-codalario-serie-genero-chico", "fecha": "2026-09-06", "medio": "Codalario", "url": "https://www.codalario.com/nuria-blanco-alvarez/portada/articulo-tipologias-de-genero-chico.-por-nuria-blanco-alvarez_14934_2_49738_0_1_in.html", "titulo": "Una serie de Codalario repasa qué es el género chico y cuántas clases hay dentro de él", "texto": "Codalario publica una serie divulgativa de Nuria Blanco Álvarez sobre el género chico. La primera entrega, del 30 de agosto y también en podcast, sitúa su origen en el teatro por horas: cuatro piezas de una hora a lo largo de la tarde, a precios asequibles. La segunda, del 6 de septiembre, sostiene que el nombre alude solo a la duración y no a la calidad, y distingue sainetes líricos, juguetes líricos, parodias musicales, revistas y zarzuelas breves, costumbristas o cómicas. La autora anuncia más entregas sobre cada tipo.", "etiquetas": ["divulgación", "género chico", "siglo XIX"], "pais": "ES", "anio": "2026", "obras": [{"id": "la-verbena-de-la-paloma", "t": "La verbena de la Paloma"}, {"id": "la-revoltosa", "t": "La revoltosa"}, {"id": "la-cancion-de-la-lola", "t": "La canción de la Lola"}, {"id": "la-gran-via", "t": "La Gran Vía"}, {"id": "chateau-margaux", "t": "Chateau-Margaux"}, {"id": "la-viejecita", "t": "La viejecita"}, {"id": "gigantes-y-cabezudos", "t": "Gigantes y cabezudos"}, {"id": "el-duo-de-la-africana", "t": "El dúo de La africana"}, {"id": "cuba-libre", "t": "¡Cuba libre!"}], "personas": [{"id": "tomas-breton", "n": "Tomás Bretón"}, {"id": "ruperto-chapi", "n": "Ruperto Chapí"}, {"id": "federico-chueca", "n": "Federico Chueca"}, {"id": "joaquin-valverde-duran", "n": "Joaquín Valverde Durán"}, {"id": "manuel-fernandez-caballero", "n": "Manuel Fernández Caballero"}, {"id": "mariano-hermoso", "n": "Mariano Hermoso"}, {"id": "reveriano-soutullo", "n": "Reveriano Soutullo"}, {"id": "juan-vert", "n": "Juan Vert"}, {"id": "guillermo-perrin", "n": "Guillermo Perrín"}, {"id": "miguel-de-palacios", "n": "Miguel de Palacios"}, {"id": "jose-lopez-silva", "n": "José López Silva"}, {"id": "carlos-arniches", "n": "Carlos Arniches"}, {"id": "ricardo-de-la-vega", "n": "Ricardo de la Vega"}], "comp": [{"t": "consta", "txt": "Los nueve títulos que la serie pone como ejemplo tienen ficha en la Zarzuteca, y el género que consta en cada una es el que describe el artículo: «La verbena de la Paloma», «La revoltosa», «La canción de la Lola» y «Cuba libre» son sainetes líricos; «Chateau Margaux», juguete cómico-lírico; «La viejecita», «Gigantes y cabezudos» y «El dúo de La Africana», zarzuelas cómicas; y «La Gran Vía», revista madrileña cómico-lírica, fantástico-callejera.", "ficha": null}, {"t": "aporta", "txt": "Las parejas de autores que cita la serie se pueden seguir en el catálogo: Chueca y Valverde Durán firman juntos «La canción de la Lola» (1880) y «La Gran Vía» (1886), y de Fernández Caballero hay cuatro de los títulos citados, entre 1887 y 1898.", "ficha": {"tipo": "persona", "id": "manuel-fernandez-caballero", "n": "Manuel Fernández Caballero"}}, {"t": "nocons", "txt": "Las dos parodias que cita el artículo, «Lorencín» y «El camarero del cine», no constan en el catálogo publicado, ni tampoco «Un caballero particular», «El loco de la guardilla», «La camisa de la Lola» ni «Un cocinero», del primer artículo.", "ficha": null}, {"t": "nocons", "txt": "De las parejas de libretistas, el catálogo tiene a Perrín y Palacios, a López Silva y a Arniches, pero no a Mauricio Gullón; y «Luis de Larra» no se enlaza porque hay dos en el catálogo, Luis Mariano de Larra y Wetoret y su hijo Luis de Larra y Ossorio, y el artículo no dice cuál. La clasificación de tipologías es de la autora, que discute con las de Emilio Casares y Pilar Espín Templado: la nota dice qué sostiene y no la suscribe.", "ficha": null}]}, {"id": "2026-09-01-oa289-verbena-cd", "fecha": "2026-09-01", "medio": "Ópera Actual", "url": "https://www.operaactual.com/opinion/mi-version-favorita-oa-289-la-verbena-de-la-paloma-en-cd/", "titulo": "«Mi versión favorita» de Ópera Actual repasa la discografía de «La verbena de la Paloma»", "texto": "La sección «Mi versión favorita» del número 289 de Ópera Actual se ocupa de La verbena de la Paloma en disco. Javier Pérez Senz y Jaume Radigales repasan su historia discográfica, de los registros de Antonio Capdevila y Daniel Montorio en los años treinta y cuarenta a los de Ataúlfo Argenta, Rafael Ferrer, Moreno Torroba y García Asensio, y señalan como referencia moderna la grabación de 1994 dirigida por Antoni Ros Marbà, con Plácido Domingo y María Bayo, publicada por Auvidis Valois y reeditada por Naïve.", "etiquetas": ["grabación", "discografía", "revista"], "pais": "ES", "anio": "2026", "obras": [{"id": "la-verbena-de-la-paloma", "t": "La verbena de la Paloma"}], "personas": [{"id": "tomas-breton", "n": "Tomás Bretón"}, {"id": "ricardo-de-la-vega", "n": "Ricardo de la Vega"}], "comp": [{"t": "consta", "txt": "La verbena de la Paloma, con música de Tomás Bretón y libreto de Ricardo de la Vega, consta así en el catálogo.", "ficha": null}, {"t": "aporta", "txt": "Se estrenó el 17 de febrero de 1894 en el Teatro Apolo de Madrid.", "ficha": {"tipo": "obra", "id": "la-verbena-de-la-paloma", "n": "La verbena de la Paloma"}}, {"t": "nocons", "txt": "El archivo de INNAZ no registra grabaciones: los sellos, los años y los intérpretes citados quedan fuera de lo que aquí se puede comprobar.", "ficha": null}]}, {"id": "2026-09-01-oa289-estudio-lirico-hispano", "fecha": "2026-09-01", "medio": "Ópera Actual", "url": "https://www.operaactual.com/reportaje/estudio-de-oa-289-la-buena-salud-de-la-zarzuela-y-de-la-opera-espanola/", "titulo": "Ópera Actual dedica su estudio de septiembre a la temporada del teatro lírico hispano", "texto": "El número 289 de Ópera Actual dedica su estudio al teatro lírico hispano y lo ordena en cuatro vías: recuperación patrimonial, revisión escénica, creación de repertorio nuevo y proyección internacional. Entre lo anunciado, el Gran Teatre del Liceu prevé para 2027, en versión de concierto, la zarzuela Cançó d'amor i de guerra, de Rafael Martínez Valls, y Schiava e Regina, de Lluïsa Casagemas, ópera programada en la temporada 1893-94 y cancelada tras el atentado de aquel año. El Teatro de la Zarzuela estrena Las trece rosas y programa Poeta en Nueva York.", "etiquetas": ["temporada", "patrimonio", "revista"], "pais": "ES", "anio": "2026", "obras": [], "personas": [], "comp": [{"t": "consta", "txt": "Cançó d’amor i de guerra, con música de Rafael Martínez Valls, consta en el catálogo.", "ficha": null}, {"t": "aporta", "txt": "Se estrenó el 16 de abril de 1926 en el Teatre Nou de Barcelona, con libreto de Lluís Capdevila y Víctor Mora, que la noticia no nombra. Su ficha aún no está publicada.", "ficha": null}, {"t": "nocons", "txt": "Ni Schiava e Regina ni Lluïsa Casagemas figuran hoy en el catálogo.", "ficha": null}]}, {"id": "2026-09-01-oa289-barbieri", "fecha": "2026-09-01", "medio": "Ópera Actual", "url": "https://www.operaactual.com/historia-de-la-opera/oa-289-historia-de-la-zarzuela-xix-francisco-asenjo-barbieri/", "titulo": "La serie de historia de la zarzuela de Ópera Actual dedica su entrega decimonovena a Barbieri", "texto": "La serie sobre historia de la zarzuela de Ópera Actual dedica su entrega decimonovena a Francisco Asenjo Barbieri (Madrid, 1823-1894). El texto, firmado por Verónica Maynés, recorre su única ópera, Il Buontempone, cuyo estreno en 1847 quedó abortado por los disturbios de la Segunda Guerra Carlista, y su papel como impulsor de un teatro lírico propio, primero desde la revista La España musical y después con la Sociedad de Artistas, que fundó en 1851 junto a Rafael Hernando, Cristóbal Oudrid, José Inzenga, Joaquín Gaztambide, Luis de Olona y Francisco Salas.", "etiquetas": ["divulgación", "siglo XIX", "revista"], "pais": "ES", "anio": "2026", "obras": [{"id": "jugar-con-fuego", "t": "Jugar con fuego"}, {"id": "pan-y-toros", "t": "Pan y toros"}, {"id": "el-barberillo-de-lavapies", "t": "El barberillo de Lavapiés"}, {"id": "chorizos-y-polacos", "t": "Chorizos y polacos"}], "personas": [{"id": "francisco-asenjo-barbieri", "n": "Francisco Asenjo Barbieri"}, {"id": "rafael-hernando", "n": "Rafael Hernando"}, {"id": "cristobal-oudrid", "n": "Cristóbal Oudrid"}, {"id": "jose-inzenga", "n": "José Inzenga"}, {"id": "joaquin-gaztambide", "n": "Joaquín Gaztambide"}, {"id": "luis-olona", "n": "Luis Olona"}], "comp": [{"t": "consta", "txt": "La Sociedad de Artistas y sus seis socios —Olona, Salas, Gaztambide, Oudrid, Hernando e Inzenga— constan así en nuestras fuentes.", "ficha": null}, {"t": "consta", "txt": "Barbieri, nacido en Madrid en 1823 y muerto en Madrid en 1894.", "ficha": null}, {"t": "aporta", "txt": "Aquella compañía estrenó Jugar con fuego el 6 de octubre de 1851 en el Teatro del Circo de Madrid.", "ficha": {"tipo": "obra", "id": "jugar-con-fuego", "n": "Jugar con fuego"}}, {"t": "nocons", "txt": "Nuestras fuentes datan en 1851 el alquiler del Teatro del Circo por esa sociedad; el año de su fundación no consta en ellas.", "ficha": null}, {"t": "nocons", "txt": "El estreno frustrado de Il Buontempone en 1847 no consta en nuestras fuentes.", "ficha": null}]}];
